import{z as o,x as A,o as i,c,q as E,j as r,D as s,d as t,s as B,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"tickless","description":"","frontmatter":{"title":"tickless","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tickless-nohz.md","filePath":"cs/tickless-nohz.md","lastUpdated":1791063341000}'),d={name:"cs/tickless-nohz.md"};function p(k,e,h,u,m,f){const l=A("Mermaid");return i(),c("div",null,[e[2]||(e[2]=E('<h1 id="tickless" tabindex="-1">tickless <a class="header-anchor" href="#tickless" aria-label="Permalink to &quot;tickless&quot;">​</a></h1><div class="epigraph"><p>NO_HZ 在核空闲（或甚至有任务但动态）时关掉周期性调度 tick，用 hrtimer 在真正需要时再响，让 C-state 能睡稳。</p><footer>—— 据 Linux timers/NO_HZ 文档；Corbet 对 tickless 的 LWN 整理</footer></div><p><a href="/cs/cpuidle-cstate">cpuidle</a> 被周期性 tick 吵醒就进不了深 C。<a href="/cs/eevdf">EEVDF</a> 仍要记账。缺口是 <strong>tickless</strong>：idle 与 full dynticks 的差别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 HZ 次/秒中断，空闲也响。<code>NO_HZ_IDLE</code>：空闲停 tick。<code>NO_HZ_FULL</code>：隔离核上单任务也可停，给 HPC/RT。缺口：时间会计靠进入/退出补；POSIX CPU 时钟变粗；RCU 回调要有核处理。本课不把所有 nohz 限制列出。</p><p><span class="marginnote">隔离核仍要偶尔处理 IPIs。对象是时钟中断策略，不是用户 crontab。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>idle 入口：取消 tick，设下一个需要的 hrtimer。busy nohz full：把该 CPU 移出常规 tick 掩码。对照 <a href="/cs/napi">NAPI</a>：包 IRQ 仍在。对照 cyclictest：tick 本身是抖动源。对照 <a href="/cs/kpti-os">KPTI</a>：无关页表。</p>',8)),(i(),r(n,null,{default:s(()=>[B(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDLE%5B%22%E8%BF%9B%E5%85%A5%E7%A9%BA%E9%97%B2%22%5D%20--%3E%20STOP%5B%22%E5%81%9C%E5%91%A8%E6%9C%9F%E6%80%A7%20tick%22%5D%0A%20%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E4%BB%B6%E5%88%B0%E6%9C%9F%E4%BA%8B%22%5D%20--%3E%20HRT%5B%22hrtimer%22%5D%0A%20%20HRT%20--%3E%20WAKE%5B%22%E5%86%8D%E5%93%8D%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[t("tickless 把「OS 心跳」从固定频率变成事件驱动，服务功耗与隔离核确定性。记账与 RCU 是税。不要写成取消调度。与 "),a("a",{href:"/cs/fairness-metrics"},"fairness"),t("：无 tick 时份额靠其它更新点。")],-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：「tick」就是内核每秒几百上千次的定时心跳，用来记账时间和检查调度。tickless 就是把固定心跳改成事件驱动：没事做就关表，有事了再上一个一次性的闹钟。")],-1)),e[6]||(e[6]=a("p",null,"两档 NO_HZ 的边界与各自的税：",-1)),(i(),r(n,null,{default:s(()=>[B(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22NO_HZ_IDLE%22%5D%20--%3E%20A1%5B%22%E5%8F%AA%E5%9C%A8%E6%A0%B8%E7%A9%BA%E9%97%B2%E6%97%B6%E5%81%9C%20tick%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E8%AE%B0%E8%B4%A6%E9%9D%A0%E8%BF%9B%E5%87%BA%E7%A9%BA%E9%97%B2%E8%A1%A5%22%5D%0A%20%20B%5B%22NO_HZ_FULL%22%5D%20--%3E%20B1%5B%22%E9%9A%94%E7%A6%BB%E6%A0%B8%E4%B8%8A%E5%8D%95%E4%BB%BB%E5%8A%A1%E4%B9%9F%E5%81%9C%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E8%A6%81%E6%B1%82%3A%20%E6%A0%B8%E4%B8%8A%E5%87%A0%E4%B9%8E%E6%B2%A1%E6%9C%89%E5%88%AB%E7%9A%84%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20B2%20--%3E%20B3%5B%22RCU%20%E5%9B%9E%E8%B0%83%E8%A6%81%E5%88%AB%E7%9A%84%E6%A0%B8%E4%BB%A3%E8%B7%91%22%5D%0A%20%20A2%20--%3E%20C%5B%22%E6%94%B6%E7%9B%8A%3A%20C-state%20%E7%9D%A1%E5%BE%97%E6%B7%B1%22%5D%0A%20%20B3%20--%3E%20D%5B%22%E6%94%B6%E7%9B%8A%3A%20%E4%B8%8D%E8%A2%AB%E5%91%A8%E6%9C%9F%E4%B8%AD%E6%96%AD%E6%89%93%E6%96%AD%22%5D%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=E('<p>full nohz 配置错误会导致时间不准或 RCU stall。</p><p>实现上：full nohz 要求该 CPU 上几乎只有一个任务，RCU 回调要有人代跑。POSIX CPU 时钟会计变粗。隔离后仍可能被 IPI 和定时器打醒。 读法上只引用<a href="/cs/cpuidle-cstate">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>tickless</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><p><span class="marginnote">数字实例：取 HZ=250——CPU 完全空闲时，每 4 毫秒也要被中断一次，一小时白醒 90 万次，每次都要退出深 C-state 再爬回去。停掉空闲 tick 后省下的正是这几十万次进出，功耗差距可以有几十个百分点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 xen 偷 tick 的全部。不保证虚拟化 guest 的 nohz。调度课序收口于定时器实现：timer wheel。</p><p>版本字段会变，课序钉的是机制对象「tickless」，不是某一主线内核的结构体名。 后课默认：空闲可停 HZ tick。内核如何组织大量定时器，下一课定时器轮。</p><p><span class="marginnote">常见误区：初学者容易把 tickless 理解成「取消时间」——时间照走，只是不再定期打断 CPU：进空闲时记下时刻，退出时一减就把账补回来。代价是 POSIX CPU 时钟这类按 tick 计量的接口变粗。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NO_HZ 停周期性 tick，改用 hrtimer。</li><li>full nohz 服务隔离核，约束多。</li><li>定时器轮是下一课。</li><li>出处：Linux NO_HZ；LWN tickless。</li></ul>',11))])}const C=o(d,[["render",p]]);export{D as __pageData,C as default};
